namespace Shop.Api.Data;

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;
using Microsoft.Extensions.Configuration;

/// <summary> The EF Core context over the shop.db database (SQLite). Generated by CS_DbContext: add your own parts in another file of this partial class.
/// Needs the NuGet packages Microsoft.EntityFrameworkCore.Sqlite and Microsoft.Extensions.Configuration.Json. </summary>
public partial class ShopContext : DbContext
{
    public DbSet<Customer> Customer => Set<Customer>();
    public DbSet<Product> Product => Set<Product>();
    public DbSet<SalesOrder> SalesOrder => Set<SalesOrder>();

    public ShopContext()
    {
    }

    public ShopContext(DbContextOptions<ShopContext> options) : base(options)
    {
    }

    // SQLite stores a decimal as text, a DateTimeOffset and a TimeSpan in forms it can neither order nor compare in SQL (ORDER BY on them fails), so they
    // are stored as a double, a binary value and a tick count. A double holds the usual money amounts well enough; change the conversion if you need exact cents.
    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        configurationBuilder.Properties<decimal>().HaveConversion<double>();
        configurationBuilder.Properties<decimal?>().HaveConversion<double>();
        configurationBuilder.Properties<DateTimeOffset>().HaveConversion<DateTimeOffsetToBinaryConverter>();
        configurationBuilder.Properties<DateTimeOffset?>().HaveConversion<DateTimeOffsetToBinaryConverter>();
        configurationBuilder.Properties<TimeSpan>().HaveConversion<TimeSpanToTicksConverter>();
        configurationBuilder.Properties<TimeSpan?>().HaveConversion<TimeSpanToTicksConverter>();
    }

    /// <summary> The one place the database provider is chosen; the API registration calls it too. </summary>
    public static void UseProvider(DbContextOptionsBuilder options, string? connectionString)
    {
        options.UseSqlite(connectionString);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        if (!optionsBuilder.IsConfigured)
        {
            IConfigurationRoot configuration = new ConfigurationBuilder()
                .SetBasePath(AppContext.BaseDirectory)
                .AddJsonFile("appsettings.json")
                .Build();
            UseProvider(optionsBuilder, configuration.GetConnectionString("DbConnectionString"));
        }
    }
}
